#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

SOURCE="mattpocock/skills"
LOCK="skills-lock.json"
SKILL_PATHS=(.agents/skills .claude/skills "$LOCK")
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

cd "$(git rev-parse --show-toplevel)"

# upstream_skills: every skill folder upstream, except the deprecated bucket.
# Aborts on a truncated tree, since a partial list would fake drift.
upstream_skills() {
  gh api "repos/$SOURCE/git/trees/HEAD?recursive=1" > "$WORK/tree.json"
  if [[ "$(jq -r '.truncated' "$WORK/tree.json")" != "false" ]]; then
    printf '  %s✗ GitHub returned a truncated tree for %s; the drift check would be wrong%s\n' "$RED" "$SOURCE" "$RESET" >&2
    exit 1
  fi
  jq -r '.tree[].path | select(test("^skills/.*/SKILL.md$")) | select(test("^skills/deprecated/") | not) | split("/")[-2]' "$WORK/tree.json" |
    sort -u
}

# head_locked_skills: the skills from SOURCE in the committed lock, if any.
head_locked_skills() {
  { git show "HEAD:$LOCK" 2>/dev/null || echo '{"skills":{}}'; } |
    jq -r --arg src "$SOURCE" '.skills | to_entries[] | select(.value.source == $src) | .key' | sort -u
}

# locked_skills: every skill this repo installed from SOURCE.
locked_skills() {
  jq -r --arg src "$SOURCE" '.skills | to_entries[] | select(.value.source == $src) | .key' "$LOCK" | sort -u
}

# compute_drift fills NEW (upstream only) and GONE (lock only).
compute_drift() {
  upstream_skills > "$WORK/upstream"
  locked_skills > "$WORK/lock"
  NEW=$(comm -23 "$WORK/upstream" "$WORK/lock")
  GONE=$(comm -13 "$WORK/upstream" "$WORK/lock")
}

show_drift() {
  if [[ -z "$NEW" && -z "$GONE" ]]; then
    printf '  %s✓ in sync%s: %s skills upstream, all in %s\n' "$GREEN" "$RESET" "$(wc -l < "$WORK/upstream" | tr -d ' ')" "$LOCK"
    return
  fi
  if [[ -n "$GONE" ]]; then
    warn "In $LOCK but gone upstream (deleted, or the old name of a renamed skill):"
    while read -r s; do note "  - $s"; done <<< "$GONE"
  fi
  if [[ -n "$NEW" ]]; then
    say "Upstream but not installed (new, a new name, or one you skipped on purpose):"
    while read -r s; do note "  - $s"; done <<< "$NEW"
  fi
}

banner "Update $SOURCE skills"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Preflight"
missing=()
for cmd in git gh jq npx; do command -v "$cmd" >/dev/null 2>&1 || missing+=("$cmd"); done
if (( ${#missing[@]} )); then
  printf '  %s✗ missing: %s%s\n' "$RED" "${missing[*]}" "$RESET"; exit 1
fi
gh auth status >/dev/null 2>&1 || { printf '  %s✗ gh is not logged in: run gh auth login%s\n' "$RED" "$RESET"; exit 1; }
printf '  %s✓%s git, gh, jq, npx present; gh logged in\n' "$GREEN" "$RESET"
if [[ -n "${CLAUDECODE:-}" ]]; then
  warn "This shell runs inside Claude Code. The skills CLI detects that and skips its prompts."
  warn "Run this wizard from a normal terminal instead."
  confirm "Continue anyway?" || exit 1
fi
dirty=$(git status --porcelain -- "${SKILL_PATHS[@]}")
if [[ -n "$dirty" ]]; then
  warn "Skill files already have uncommitted changes:"
  printf '%s\n' "$dirty" | sed 's/^/    /'
  note "The update diff will mix with these changes."
  confirm "Continue anyway?" || exit 1
else
  printf '  %s✓%s skill files are clean\n' "$GREEN" "$RESET"
fi
note "Branch: $(git branch --show-current)"
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Add: pull updates and new skills"
say "Run the skills CLI and answer its prompts:"
step "Skills: select every skill you keep. Leave out the ones you removed on purpose."
step "Agents: the same harnesses as last time (copies live in .agents/skills, links in .claude/skills)."
step "Install method: Symlink."
step "Scope: Project."
printf '\n    %snpx skills@latest add %s%s\n\n' "$BOLD" "$SOURCE" "$RESET"
if confirm "Run it here now? (No = you run it in another terminal)"; then
  npx skills@latest add "$SOURCE" || warn "the skills CLI exited with an error; check its output above"
fi
pause "Press Enter when the add is done"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Drift check: upstream vs $LOCK"
say "Comparing the skill folders upstream with ${LOCK}…"
compute_drift
show_drift
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Remove: skills gone upstream"
if [[ -z "$GONE" ]]; then
  printf '  %s✓%s nothing to remove\n' "$GREEN" "$RESET"
else
  # Read the list on fd 3 so confirm and npx keep the terminal on stdin.
  while read -r s <&3; do
    path=$(jq -r --arg s "$s" '.skills[$s].skillPath' "$LOCK")
    printf '\n  %s%s%s  %s(was %s)%s\n' "$BOLD" "$s" "$RESET" "$DIM" "$(dirname "$path")" "$RESET"
    note "Last upstream commit on that path (its message names any replacement):"
    gh api "repos/$SOURCE/commits?path=$(dirname "$path")&per_page=1" \
      --jq '.[0] | .sha[:7] + " " + .commit.author.date[:10] + "  " + .commit.message' 2>/dev/null |
      head -n 12 | sed 's/^/      /' || note "  (no commit history found)"
    printf '\n    %snpx skills@latest remove -s %s%s\n' "$BOLD" "$s" "$RESET"
    if confirm "Run it here now? (No = run it yourself, or keep the skill)"; then
      npx skills@latest remove -s "$s" || warn "the skills CLI exited with an error; check its output above"
    fi
  done 3<<< "$GONE"
  note "If a replacement is named above and not installed, add it: npx skills@latest add $SOURCE -s <name>"
fi
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Review the changes"
git status --short -- "${SKILL_PATHS[@]}" | sed 's/^/    /'
# Whole new skill roots only; new files inside an existing skill show in the status above.
new_dirs=$(git ls-files --others --exclude-standard --directory -- .agents/skills | grep -E '^\.agents/skills/[^/]+/$' || true)
if [[ -n "$new_dirs" ]]; then
  printf '\n'; say "New skill folders (check you want each one):"
  while read -r d; do
    desc=$(sed -n 's/^description: *//p' "${d}SKILL.md" 2>/dev/null | head -n 1 | cut -c1-140 || true)
    [[ -n "$desc" ]] || desc="(no SKILL.md description)"
    printf '    %s%s%s  %s%s%s\n' "$BOLD" "$(basename "$d")" "$RESET" "$DIM" "$desc" "$RESET"
  done <<< "$new_dirs"
  note "To drop one: npx skills@latest remove -s <name>"
fi
pause "Press Enter when the review is done (run any extra removes first)"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Re-check and commit"
compute_drift
show_drift
if [[ -n "$GONE" ]]; then
  warn "Skills gone upstream are still installed. Fix that first or commit anyway."
fi
if [[ -z "$(git status --porcelain -- "${SKILL_PATHS[@]}")" ]]; then
  note "No skill changes to commit."
else
  branch=$(git branch --show-current)
  if [[ "$branch" == "main" ]] && confirm "You are on main. Create branch chore/skills-update-$(date +%F)?"; then
    git switch -c "chore/skills-update-$(date +%F)"
  fi
  git add -A -- "${SKILL_PATHS[@]}"
  git diff --cached --stat | sed 's/^/    /'
  added=$(comm -13 <(head_locked_skills) <(locked_skills) | paste -sd, - | sed 's/,/, /g')
  removed=$(comm -23 <(head_locked_skills) <(locked_skills) | paste -sd, - | sed 's/,/, /g')
  body="Update the skills installed from $SOURCE."
  [[ -n "$added" ]] && body+=$'\n\n'"Added: $added."
  [[ -n "$removed" ]] && body+=$'\n\n'"Removed: $removed."
  printf '\n%s\n' "chore(skills): update $SOURCE" ; printf '%s\n' "$body" | sed 's/^/    /'
  if confirm "Commit the staged skill changes with this message?"; then
    # The pathspec commits only the skill paths, never other staged files.
    git commit -q -m "chore(skills): update $SOURCE" -m "$body" -- "${SKILL_PATHS[@]}"
    printf '  %s✓ committed%s %s\n' "$GREEN" "$RESET" "$(git log -1 --format='%h %s')"
  else
    SKIPPED+=("commit: changes are staged, commit them yourself")
  fi
fi
pause

finish
